from fastapi import APIRouter, Depends, HTTPException
from fastapi.responses import FileResponse
import os

router = APIRouter(prefix="/analytics/exports")

@router.get("/{export_job_id}/download")
async def download_duckdb_export_file(
    export_job_id: str,
    export_store: ExportJobStore = Depends(get_export_job_store),
    current_user: User = Depends(get_current_user)
):
    job = await export_store.get_export_job(export_job_id)
    if not job or job.tenant_id != current_user.tenant_id:
        raise HTTPException(status_code=404, detail="Export job not found")

    if not os.path.exists(job.file_path):
        raise HTTPException(status_code=404, detail="Export file not ready or expired")

    return FileResponse(
        path=job.file_path,
        filename=f"analytics_{export_job_id}.parquet",
        media_type="application/octet-stream"
    )
